// 只覆写 equals 不够：哈希不同，HashSet 根本不会调 equals
class SongV4 implements Comparable<SongV4> {
  private String title;
  private String artist;
  private int bpm;

  @Override
  public boolean equals(Object aSong) {
    SongV4 other = (SongV4) aSong;
    return title.equals(other.getTitle());    // 委托给 String 的 equals
  }

  @Override
  public int hashCode() {
    return title.hashCode();                  // 必须和 equals 用同一个字段
  }

  @Override
  public int compareTo(SongV4 s) {
    return title.compareTo(s.getTitle());
  }
}

